def F(title,eq,sub,meaning,notes='Article worked example and saved workbook evidence; preserve their separate assumptions.'):
 return dict(title=title,equation=eq,substitution=sub,interpretation=meaning,notes=notes)
def S(title,base,changed,result,notes='Teaching sensitivity; hold other assumptions fixed unless a multi-input case is explicitly named.'):
 return dict(title=title,baseline=base,changed=changed,consequence=result,notes=notes)
def B(title,*points): return dict(title=title,points=list(points),notes='Explain the mechanism with the cited article section, then relate it to the opening decision.')
